"}, {"source": "remediation_change_log:98043", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:98044", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s007: period_start ''-4000'' -> None"}, {"source": "remediation_change_log:247891", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:247892", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s006: period_start None -> ''-4000''"}, {"source": "remediation_change_log:348174", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:348175", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s003: period_start ''-4000'' -> None"}]'::jsonb),
