.\""}, {"source": "remediation_change_log:100857", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:100858", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s010: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:151756", "url": "remediation_change_log", "quote": "served-image-2026-09-30-014: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/6/6b/Wapley_Hill_-_geograph.org.uk_-_62890.jpg'' -> ''/data/images/wiki/67b3a2f7/hero.webp''"}, {"source": "remediation_change_log:249253", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249254", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-800''"}, {"source": "remediation_change_log:385832", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s002: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:385833", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s002: period_start ''-800'' -> None"}, {"source": "remediation_change_log:400383", "url": "remediation_change_log", "quote": "2026-11-07c_mechanical-period-fix-s002: period_name ''Undated'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:400384", "url": "remediation_change_log", "quote": "2026-11-07c_mechanical-period-fix-s002: period_start None -> ''-1500''"}]'::jsonb),
