astal erosion [1].''"}, {"source": "remediation_change_log:102685", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:102686", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:250607", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:250608", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s012: period_start None -> ''-800''"}, {"source": "remediation_change_log:386530", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:386531", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_start ''-800'' -> None"}, {"source": "remediation_change_log:400495", "url": "remediation_change_log", "quote": "2026-11-07c_mechanical-period-fix-s002: period_name ''Undated'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:400496", "url": "remediation_change_log", "quote": "2026-11-07c_mechanical-period-fix-s002: period_start None -> ''-1500''"}]'::jsonb),
