    ('9bedafde-94b7-40d2-a064-4130c224d7ef'::uuid, 'mystery', '5', '6', 'card-stats-2026-11-07c-rollback:9bedafde-94b7-40d2-a064-4130c224d7ef:mystery', 'rollback of card-stats-2026-11-07c: mystery ''6'' restored on Fraubillen Cross', '4528823582dfae2e80cb303265bde9d9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 5 from (''Megalithic stones'', ''3000 - 1500 BC'') is shared by 28 curated site(s)"}, {"source": "production export 80b2b77ea294dfe0 (2026-11-07 13:29:26.934212+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 766 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07''s own export (2026-11-07 10:00:39.847916+00))"}, {"source": "remediation_change_log:86330", "url": "remediation_change_log", "quote": "phase4:p4-2139:chunk-0001: description \"The Fraubillen Cross (Fraubillenkreuz) is a roughly 5,000-year-old Neolithic menhir that was resculpted into a Christian cross, standing 3.5 metres high on the Ferschweiler Plateau in the Eifel mountains of Germany. According to tradition, the Anglo-Saxon missionary Willibrord transformed the pagan stone into a cross shape in the 8th century. The name may derive from ''Our Lady''s picture cross'' or from ''Sybillenkreuz,'' referencing pre-Christian prophetic women. First documented in 1470 as ''la Grande Croix'' marking the boundary between Nassau and Burgundy territories, it still serves as a district boundary marker today.\" -> ''The Fraubillen cross (German: Fraubillenkreuz) is a menhir, which has been resculpted into a cross [1]. It stands by a wayside on the Ferschweiler Plateau in the Eifel mountains in Germany, between Ferschweiler, Schankweiler, Nusbaum-Rohrbach and Bollendorf [1]. According to tradition, the celebrated missionary in the Eifel region, Willibrord refashioned the roughly 5,000-year-old menhir by hand into the shape of a cross as a Christian monument [1]. Two niches for figures have been chiselled into the rock, each surrounded by holes [1]. Today, the cross is about 3.5 metres high [1].''"}, {"source": "remediation_change_log:104343", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104344", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:156857", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9bedafde/hero.webp'' -> ''/data/images/wiki/9bedafde/Fraubillenkreuz ferschweiler plateau eifel 2.webp''"}, {"source": "remediation_change_log:240707", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:240708", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-3000''"}, {"source": "remediation_change_log:334642", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/9bedafde/Fraubillenkreuz ferschweiler plateau eifel 2.webp'' -> ''/data/images/wiki/9bedafde/hero.webp''"}]'::jsonb),
    ('9bedafde-94b7-40d2-a064-4130c224d7ef'::uuid, 'rarity_score', '29', '32', 'card-stats-2026-11-07c-rollback:9bedafde-94b7-40d2-a064-4130c224d7ef:rarity_score', 'rollback of card-stats-2026-11-07c: rarity_score ''32'' restored on Fraubillen Cross', '4528823582dfae2e80cb303265bde9d9', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 29 from mystery 5, cultural_influence 7"}, {"source": "production export 80b2b77ea294dfe0 (2026-11-07 13:29:26.934212+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 766 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07''s own export (2026-11-07 10:00:39.847916+00))"}, {"source": "remediation_change_log:86330", "url": "remediation_change_log", "quote": "phase4:p4-2139:chunk-0001: description \"The Fraubillen Cross (Fraubillenkreuz) is a roughly 5,000-year-old Neolithic menhir that was resculpted into a Christian cross, standing 3.5 metres high on the Ferschweiler Plateau in the Eifel mountains of Germany. According to tradition, the Anglo-Saxon missionary Willibrord transformed the pagan stone into a cross shape in the 8th century. The name may derive from ''Our Lady''s picture cross'' or from ''Sybillenkreuz,'' referencing pre-Christian prophetic women. First documented in 1470 as ''la Grande Croix'' marking the boundary between Nassau and Burgundy territories, it still serves as a district boundary marker today.\" -> ''The Fraubillen cross (German: Fraubillenkreuz) is a menhir, which has been resculpted into a cross [1]. It stands by a wayside on the Ferschweiler Plateau in the Eifel mountains in Germany, between Ferschweiler, Schankweiler, Nusbaum-Rohrbach and Bollendorf [1]. According to tradition, the celebrated missionary in the Eifel region, Willibrord refashioned the roughly 5,000-year-old menhir by hand into the shape of a cross as a Christian monument [1]. Two niches for figures have been chiselled into the rock, each surrounded by holes [1]. Today, the cross is about 3.5 metres high [1].''"}, {"source": "remediation_change_log:104343", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:104344", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:156857", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''/data/images/wiki/9bedafde/hero.webp'' -> ''/data/images/wiki/9bedafde/Fraubillenkreuz ferschweiler plateau eifel 2.webp''"}, {"source": "remediation_change_log:240707", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_name None -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:240708", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s007: period_start None -> ''-3000''"}, {"source": "remediation_change_log:334642", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''/data/images/wiki/9bedafde/Fraubillenkreuz ferschweiler plateau eifel 2.webp'' -> ''/data/images/wiki/9bedafde/hero.webp''"}]'::jsonb),
