    ('afa52222-ee6e-4b90-aae8-3078dae3ae71'::uuid, 'rarity_score', '21', '24', 'card-stats-2026-11-07c-rollback:afa52222-ee6e-4b90-aae8-3078dae3ae71:rarity_score', 'rollback of card-stats-2026-11-07c: rarity_score ''24'' restored on Norsebury Ring', 'fd4574378841a47b3b17f10815cf4e7b', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "rarity_score = 21 from mystery 1, cultural_influence 8"}, {"source": "production export 80b2b77ea294dfe0 (2026-11-07 13:29:26.934212+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 766 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07''s own export (2026-11-07 10:00:39.847916+00))"}, {"source": "remediation_change_log:86778", "url": "remediation_change_log", "quote": "phase4:p4-2152:chunk-0001: description \"Norsebury Ring is an Iron Age univallate hillfort near Micheldever in Hampshire, England, enclosing just under 10 acres with a single bank and ditch. The name derives from Old English ''Naesan Byrg'' meaning ''Fort at the ness,'' later corrupted to ''Norse''. Much of the southern and eastern defenses have been ploughed away, though the north and west ramparts survive within wooded boundaries. A 1997 magnetometry survey revealed two entrances and evidence of a thriving Iron Age settlement, while fieldwalking recovered Bronze Age and Roman pottery alongside Iron Age ceramics.\" -> ''Norsebury Ring is the site of an Iron Age univallate hillfort located in Hampshire [1]. A magnetometry survey in 1997 revealed two entrances (at the southeast and southwest) and found evidence to suggest that the site had a thriving Iron Age settlement [1]. Bronze Age and Roman pottery has also been found at the site [1]. The site is located at grid reference SU491401, and lies to the east of the village of Sutton Scotney, and to the west of the village of Micheldever, in the county of Hampshire [1]. Immediately to the south lies the River Dever [1]. The site lies just off to the western side of a shallow hill, at a level of approximately 100m AOD [1].''"}, {"source": "remediation_change_log:106009", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:106010", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:159137", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/74/Hunton_Down_Lane_and_Norsebury_Ring_-_geograph.org.uk_-_153005.jpg'' -> ''https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Norsebury_Ring_Hillfort_-_geograph.org.uk_-_5617527.jpg/1280px-Norsebury_Ring_Hillfort_-_geograph.org.uk_-_5617527.jpg''"}, {"source": "remediation_change_log:251979", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:251980", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s015: period_start None -> ''-800''"}, {"source": "remediation_change_log:334705", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-002: thumbnail_url ''https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Norsebury_Ring_Hillfort_-_geograph.org.uk_-_5617527.jpg/1280px-Norsebury_Ring_Hillfort_-_geograph.org.uk_-_5617527.jpg'' -> ''/data/images/wiki/afa52222/hero.webp''"}, {"source": "remediation_change_log:386667", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:386668", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_start ''-800'' -> None"}, {"source": "remediation_change_log:401227", "url": "remediation_change_log", "quote