    ('c3ed760b-0027-4275-bed0-787ef5d7ef02'::uuid, 'antiquity', '6', '5', 'card-stats-2026-11-07c-rollback:c3ed760b-0027-4275-bed0-787ef5d7ef02:antiquity', 'rollback of card-stats-2026-11-07c: antiquity ''5'' restored on Rame Head', '024c0b817d7bb09fb3f7ef3c3d7aa01f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -1500"}, {"source": "production export 80b2b77ea294dfe0 (2026-11-07 13:29:26.934212+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 766 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07''s own export (2026-11-07 10:00:39.847916+00))"}, {"source": "remediation_change_log:87294", "url": "remediation_change_log", "quote": "phase4:p4-2167:chunk-0001: description \"Rame Head is a coastal headland in southeast Cornwall featuring an Iron Age promontory fort, or ''cliff castle'', defended by steep cliffs on three sides. The narrow neck of land connecting it to the mainland was further excavated with a deep outer ditch, earth and stone rampart, and a central causeway still visible today. The eastern part retains traces of round house platforms, though damaged by wartime construction. A medieval chapel dedicated to St Michael crowns the summit, first licensed for Mass in 1397 and probably built on the site of a Dark Age hermitage.\" -> ''Rame Head or Ram Head is a coastal headland, southwest of the village of Rame in southeast Cornwall, England, United Kingdom [1]. It is part of the larger Rame Peninsula [1]. The natural site was used for a promontory fort in the Iron Age and the narrow neck of land was further excavated on the landward side with a central causeway, still visible [1]. The eastern part retains traces of round house platforms, though damaged by wartime construction [1].''"}, {"source": "remediation_change_log:123085", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:123086", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:123087", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: site_type ''Fortress/citadel'' -> ''Fort''"}, {"source": "remediation_change_log:123088", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s008: source_url ''https://en.wikipedia.org/wiki/Rame_Head'' -> ''https://www.megalithic.co.uk/article.php?sid=10079''"}, {"source": "remediation_change_log:161428", "url": "remediation_change_log", "quote": "served-image-2026-09-30-027: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/e/ee/Ramechapel.jpg'' -> ''/data/images/wiki/c3ed760b/Rame Head (0050).webp''"}, {"source": "remediation_change_log:252875", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:252876", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s017: period_start None -> ''-800''"}, {"source": "remediation_change_log:316724", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/c3ed760b/Rame Head (0050).webp'' -> ''/data/images/wiki/c3ed760b/Ramechapel.webp''"}, {"source": "remediation_change_log:387356", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s004: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:387357", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s004: period_start ''-800'' -> None"}, {"source": "remediation_change_log:401291", "url": "remediation_change_log", "quote": "2026-11-07c_mechanical-period-fix-s003: period_name ''Undated'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:401292", "url": "remediatio