    ('d2b71745-bf32-4027-8920-18fcd5600c8d'::uuid, 'antiquity', '6', '5', 'card-stats-2026-11-07c-rollback:d2b71745-bf32-4027-8920-18fcd5600c8d:antiquity', 'rollback of card-stats-2026-11-07c: antiquity ''5'' restored on Tipón', '8d7c656733850d8fa041627bb6954509', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 6 from period_start -1500"}, {"source": "production export 80b2b77ea294dfe0 (2026-11-07 13:29:26.934212+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 766 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07''s own export (2026-11-07 10:00:39.847916+00))"}, {"source": "remediation_change_log:28776", "url": "remediation_change_log", "quote": "phase3:batch-0192:chunk-0001: period_start ''1000'' -> ''-1000''"}, {"source": "remediation_change_log:30512", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1000 - 1500 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:32432", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: period_name ''1500 - 500 BC'' -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:32433", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-journal-reversal-2: period_start ''-1000'' -> ''1000''"}, {"source": "remediation_change_log:87680", "url": "remediation_change_log", "quote": "phase4:p4-2178:chunk-0001: description ''Tipón is a sprawling early 15th-century Inca archaeological park situated 22 km southeast of Cusco at elevations between 3,250-3,960 m above sea level [1]. The site is enclosed by a 6 km defensive wall and features precise, right-angled monumental terraces irrigated by an intricate network of water canals fed by a monumental fountain originating from a natural spring [1]. Additional features include ancient residential areas and a remarkable collection of petroglyphs in the upper part of the site [1].'' -> ''The Tipón complex is located near Oropesa in the Community of Choquepata, Quispicanchi Province, southeast of Cusco [1]. The upper part of the Tipón complex is crossed by three Inca canals that divert the waters of the Pukara river and feed it for the cultivation of the entire complex; one of them flows on top of an intact stone aqueduct [1]. In 1984 Tipón was declared a National Archaeological Park of Peru and in 2006 was put on the List of Historic Civil Engineering Landmarks by the American Society of Civil Engineers [1]. The reports of the archaeological works conclude that the site was continuously occupied from the Formative stage, by the Marcavalle culture, around 1000 BCE, through the Chanapata, Qotakalli, Huari and Killke, until the Inca period [1]. Cruz Moqo is the highest point of Tipón Archaeological Park at an elevation of 3,960 metres and contains important petroglyphs [1].''"}, {"source": "remediation_change_log:108895", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:108896", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''1000'' -> None"}, {"source": "remediation_change_log:163035", "url": "remediation_change_log", "quote": "served-image-2026-09-30-029: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/a/a3/Tipon_-_Cusco.jpg'' -> ''/data/images/wiki/d2b71745/Tipon_-_Cusco.webp''"}, {"source": "remediation_change_log:243713", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:243714", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s010: period_start None -> ''-1000''"}, {"source": "remediation_change_log:352861", "url": "remediation_change_log", "quote": "2026-10-17a_fields-wd5-s008: period_name ''1500 - 500 BC''